def is_exact_response_time_analysis(analysis_method):
    # Condition (i): Safety of Bounds
    for J_i in all_jobs:
        for gamma in generate_all_execution_scenarios(J_i):
            actual_rt = calculate_response_time(J_i, gamma)
            if not (analysis_method.BCRT(J_i) <= actual_rt <= analysis_method.WCRT(J_i)):
                return False

    # Condition (ii): Tightness of Bounds
    for J_i in all_jobs:
        found_bcrt_scenario = False
        found_wcrt_scenario = False
        for gamma in generate_all_execution_scenarios(J_i):
            actual_rt = calculate_response_time(J_i, gamma)
            if actual_rt == analysis_method.BCRT(J_i):
                found_bcrt_scenario = True
            if actual_rt == analysis_method.WCRT(J_i):
                found_wcrt_scenario = True
        if not (found_bcrt_scenario and found_wcrt_scenario):
            return False

    return True

