def verify_EFT_lower_bound(job_set_J_X, system_state_v_p, computed_EFT):
    # computed_EFT is the result of compute_EFT(job_set_J_X, system_state_v_p)
    for scenario in generate_all_execution_scenarios_for_JX(job_set_J_X):
        actual_finish_time = simulate_actual_finish_time(job_set_J_X, scenario, system_state_v_p)
        if actual_finish_time < computed_EFT:
            return False # Lemma is violated
    return True # Lemma holds

def is_exact_EFT(EFT_val, J_M):
    # Condition 1: Lower Bound
    for gamma in generate_all_execution_scenarios_for_JM(J_M):
        if calculate_finish_time(J_M, gamma) < EFT_val:
            return False

    # Condition 2: Achievability
    found_achievable_scenario = False
    for gamma in generate_all_execution_scenarios_for_JM(J_M):
        if calculate_finish_time(J_M, gamma) == EFT_val:
            found_achievable_scenario = True
            break
    return found_achievable_scenario

def prove_EFT_is_exact(job_set_J_M, system_state_v_p):
    computed_EFT = compute_EFT(job_set_J_M, system_state_v_p)

    # Check Lemma 6 (lower bound)
    if not verify_EFT_lower_bound(job_set_J_M, system_state_v_p, computed_EFT):
        return False

    # Check Lemma 7 (achievability)
    if not demonstrate_EFT_achievability(job_set_J_M, system_state_v_p, computed_EFT):
        return False

    return True # If both hold, then by Definition 8, it's exact

def compute_J_delta(J_S, v_p):
    J_delta = []
    for J_i in J_S:
        C_r_max_i_v_p = get_certainly_released_jobs(J_i.r_max, J_S, v_p) # Formula (1)
        eft_of_C = compute_EFT(C_r_max_i_v_p, v_p) # Algorithm 2
        if eft_of_C < J_i.r_max:
            J_delta.append(J_i)
    return J_delta

def check_lemma_1(J_i, J_S, scheduling_policy):
    if not scheduling_policy.is_work_conserving:
        return False # Assumption not met

    # Conceptual check: if an idle interval ends after J_i.r_max,
    # and J_i is ready, then it violates work-conserving property.
    # This lemma is a direct consequence of the work-conserving definition.

def check_lemma_3(J_S_v_p, v_p, scheduling_policy):
    if not scheduling_policy.is_work_conserving:
        return False

    J_delta = compute_J_delta(J_S_v_p, v_p) # Formula (2)

    if len(J_delta) == 0:
        # This implies that for all J_i in J_S_v_p, EF_T(C(J_i.r_max, v_p), v_p) >= J_i.r_max
        # This condition, combined with work-conserving, means no idle gaps within J_S_v_p.
        return True # Lemma holds
    else:
        return False # Lemma does not apply or is false

def compute_delta_M(v_p, J_S):
    J_delta = compute_J_delta(J_S, v_p) # Formula (2)
    if not J_delta:
        return 0

    max_r_max = 0
    for J_j in J_delta:
        if J_j.r_max > max_r_max:
            max_r_max = J_j.r_max
    return max_r_max

def compute_J_high(J_S, J_P, all_jobs_J):
    J_high = []
    for J_x in all_jobs_J:
        if J_x not in J_S and J_x not in J_P:
            for J_l in J_S:
                if J_x.p < J_l.p: # Assuming lower p value means higher priority
                    J_high.append(J_x)
                    break # J_x only needs to be higher priority than one job in J_S
    return J_high

def calculate_upper_bound_start_time(J_i, J_M_v_p, v_p):
    A_max_1 = v_p.A_max_1 # Latest processor available time from v_p

    # Initial blocking term: max C_max of lower priority jobs in J_M
    max_blocking = 0
    for J_j in J_M_v_p:
        if J_i.p < J_j.p: # J_j has lower priority than J_i
            if J_j.C_max > max_blocking:
                max_blocking = J_j.C_max

    s_i_k_minus_1 = max(A_max_1, J_i.r_max - 1 + max_blocking)
    s_i_k_minus_2 = s_i_k_minus_1 # For the first iteration, assume no prior interval

    while True:
        interference_work = 0
        for J_j in J_M_v_p:
            if J_j.p < J_i.p: # J_j has higher priority than J_i
                # Check if J_j is released in the interval (s_i_k_minus_2, s_i_k_minus_1]
                if J_j.r_min > s_i_k_minus_2 and J_j.r_min <= s_i_k_minus_1:
                    interference_work += J_j.C_max

        s_i_k = s_i_k_minus_1 + interference_work

        if s_i_k == s_i_k_minus_1:
            break # Converged

        s_i_k_minus_2 = s_i_k_minus_1
        s_i_k_minus_1 = s_i_k

    return s_i_k

def check_lemma_5(J_S, v_p, J_P, all_jobs_J):
    # Condition 1: No work-conserving interference
    no_idle_interference = True
    for J_x in [job for job in all_jobs_J if job not in J_S and job not in J_P]:
        if check_lemma_4(J_x, J_S, J_P, all_jobs_J, v_p, scheduling_policy):
            no_idle_interference = False
            break

    if not no_idle_interference:
        return False

    # Condition 2: No priority-driven interference
    J_high = compute_J_high(J_S, J_P, all_jobs_J) # Formula (4)
    no_priority_interference = True
    for J_y in J_high:
        for J_l in J_S:
            if J_y.p < J_l.p: # J_y has higher priority than J_l
                # LST_l(J_S, v_p) is derived from s_l(v_p) + J_l.C_max
                s_l_v_p = calculate_upper_bound_start_time(J_l, J_S, v_p) # Formula (6)
                LST_l_J_S_v_p = s_l_v_p + J_l.C_max
                if J_y.r_min <= LST_l_J_S_v_p:
                    no_priority_interference = False
                    break
        if not no_priority_interference:
            break

    if not no_priority_interference:
        return False

    return True # J_S is a safe reduction set

