    return True # Lemma holds

def is_exact_LFT(LFT_val, J_M):
    # Condition 1: Upper Bound
    for gamma in generate_all_execution_scenarios_for_JM(J_M):
        if calculate_finish_time(J_M, gamma) > LFT_val:
            return False

    # Condition 2: Achievability
    found_achievable_scenario = False
    for gamma in generate_all_execution_scenarios_for_JM(J_M):
        if calculate_finish_time(J_M, gamma) == LFT_val:
            found_achievable_scenario = True
            break
    return found_achievable_scenario

def prove_LFT_is_exact(job_set_J_M, system_state_v_p):
    computed_LFT = compute_LFT(job_set_J_M, system_state_v_p)

    # Check Lemma 8 (upper bound)
    if not verify_LFT_upper_bound(job_set_J_M, system_state_v_p, computed_LFT):
        return False

    # Check Lemma 9 (achievability)
    if not demonstrate_LFT_achievability(job_set_J_M, system_state_v_p, computed_LFT):
        return False

    return True # If both hold, then by Definition 9, it's exact

def is_JM_schedulable(J_M, v_p):
    for J_i in J_M:
        s_i_v_p = calculate_upper_bound_start_time(J_i, J_M, v_p) # Formula (6)
        LF_T_i_J_M_v_p = s_i_v_p + J_i.C_max
        if LF_T_i_J_M_v_p > J_i.d:
            return False # J_i might miss its deadline
    return True # All jobs in J_M are schedulable
